target:
{activeCategories.map(c => (
  <linearGradient key={`grad_${c}`} id={`grad_${c}`} x1="0" y1="0" x2="0" y2="1">
    <stop offset="5%" stopColor={PRODUCT_COLORS[c]?.ach || '#94a3b8'} stopOpacity={0.8}/>
    <stop offset="95%" stopColor={PRODUCT_COLORS[c]?.ach || '#94a3b8'} stopOpacity={0}/>
  </linearGradient>
))}

replacement:
{activeCategories.map(c => (
  <linearGradient key={`grad_${c}`} id={`grad_${c.replace(/\s+/g, '_')}`} x1="0" y1="0" x2="0" y2="1">
    <stop offset="5%" stopColor={PRODUCT_COLORS[c]?.ach || '#94a3b8'} stopOpacity={0.8}/>
    <stop offset="95%" stopColor={PRODUCT_COLORS[c]?.ach || '#94a3b8'} stopOpacity={0}/>
  </linearGradient>
))}
